export class DefaultIntentResolution {
    source;
    intent;
    result;
    resultMetadata;
    constructor(result, resultMetadata, source, intent) {
        this.result = result;
        this.resultMetadata = resultMetadata;
        this.source = source;
        this.intent = intent;
        //bind all functions to allow destructuring
        this.getResult = this.getResult.bind(this);
        this.getResultMetadata = this.getResultMetadata.bind(this);
    }
    getResult() {
        return this.result;
    }
    getResultMetadata() {
        return this.resultMetadata;
    }
}
