import { AbstractListener } from './AbstractListener.js';
export class DefaultContextListener extends AbstractListener {
    channelId;
    messageType;
    contextType;
    constructor(messaging, messageExchangeTimeout, channelId, contextType, handler, messageType = 'broadcastEvent') {
        // For arrays, use the contextTypes field in the payload
        if (Array.isArray(contextType)) {
            // Use the contextTypes field for array-based context types
            super(messaging, messageExchangeTimeout, { channelId, contextType: undefined, contextTypes: contextType }, handler, 'addContextListenerRequest', 'addContextListenerResponse', 'contextListenerUnsubscribeRequest', 'contextListenerUnsubscribeResponse');
        }
        else {
            // Single context type
            super(messaging, messageExchangeTimeout, { channelId, contextType }, handler, 'addContextListenerRequest', 'addContextListenerResponse', 'contextListenerUnsubscribeRequest', 'contextListenerUnsubscribeResponse');
        }
        this.channelId = channelId;
        this.messageType = messageType;
        this.contextType = contextType;
    }
    filter(m) {
        // Handle array context types in filtering
        const contextTypeMatch = Array.isArray(this.contextType)
            ? this.contextType.includes(m.payload.context?.type ?? '')
            : m.payload.context?.type == this.contextType || this.contextType == null;
        return m.type == this.messageType && m.payload.channelId == this.channelId && contextTypeMatch;
    }
    action(m) {
        const metadata = {
            source: m.payload.metadata?.source,
            timestamp: m.payload.metadata?.timestamp ?? m.meta.timestamp,
            traceId: m.payload.metadata?.traceId,
            signature: m.payload.metadata?.signature,
            custom: m.payload.metadata?.custom,
            antiReplay: m.payload.metadata?.antiReplay,
        };
        this.handler(m.payload.context, metadata);
    }
}
