import { AbstractListener } from './AbstractListener.js';
import { v4 } from 'uuid';
export class DefaultIntentListener extends AbstractListener {
    intent;
    contextTypes;
    onUnsubscribe;
    constructor(messaging, intent, contextTypes, action, messageExchangeTimeout, onUnsubscribe) {
        super(messaging, messageExchangeTimeout, { intent, contextTypes }, action, 'addIntentListenerRequest', 'addIntentListenerResponse', 'intentListenerUnsubscribeRequest', 'intentListenerUnsubscribeResponse');
        this.intent = intent;
        this.contextTypes = contextTypes;
        this.onUnsubscribe = onUnsubscribe;
    }
    async unsubscribe() {
        await super.unsubscribe();
        this.onUnsubscribe?.();
    }
    filter(m) {
        return (m.type == 'intentEvent' &&
            m.payload.intent == this.intent &&
            (this.contextTypes == null || this.contextTypes.includes(m.payload.context.type)));
    }
    action(m) {
        const done = this.handler(m.payload.context, {
            source: m.payload.metadata?.source,
            timestamp: m.payload.metadata?.timestamp ?? m.meta.timestamp,
            traceId: m.payload.metadata?.traceId ?? v4(),
            signature: m.payload.metadata?.signature,
            custom: m.payload.metadata?.custom,
            antiReplay: m.payload.metadata?.antiReplay,
        });
        this.handleIntentResult(done, m);
    }
    intentResultRequestMessage(ir, appMetadata, m) {
        const out = {
            type: 'intentResultRequest',
            meta: {
                requestUuid: m.meta.eventUuid,
                timestamp: new Date(),
            },
            payload: {
                intentResult: convertIntentResult(ir),
                intentEventUuid: m.meta.eventUuid,
                raiseIntentRequestUuid: m.payload.raiseIntentRequestUuid,
                ...(appMetadata !== undefined && { metadata: appMetadata }),
            },
        };
        return out;
    }
    handleIntentResult(done, m) {
        if (done == null) {
            return this.messaging.exchange(this.intentResultRequestMessage(undefined, undefined, m), 'intentResultResponse', this.messageExchangeTimeout);
        }
        else {
            return done.then(raw => {
                const { result, appMetadata } = unwrapIntentResult(raw);
                return this.messaging.exchange(this.intentResultRequestMessage(result, appMetadata, m), 'intentResultResponse', this.messageExchangeTimeout);
            });
        }
    }
}
function unwrapIntentResult(raw) {
    if (raw && typeof raw === 'object' && 'context' in raw && 'metadata' in raw && !('type' in raw) && !('id' in raw)) {
        // It's a ContextWithMetadata — unwrap it
        const cwm = raw;
        return { result: cwm.context, appMetadata: cwm.metadata };
    }
    return { result: raw, appMetadata: undefined };
}
function convertIntentResult(intentResult) {
    if (!intentResult) {
        //consider any falsy result to be void...
        return {}; // void result
    }
    switch (intentResult.type) {
        case 'user':
        case 'app':
        case 'private':
            // it's a channel
            return {
                channel: {
                    type: intentResult.type,
                    id: intentResult.id,
                    displayMetadata: intentResult.displayMetadata,
                },
            };
        default:
            // it's a context
            return {
                context: intentResult,
            };
    }
}
